<template>
  <sf-sheet class="sf-premium-paywall" :class="{'is-guide':isGuide,'is-plans':isPlans,'is-compact':compact,'is-conversation':isConversation}" :open="open" :title="isGuide?$copy('paywall.guideTitle'):isPlans?$copy('paywall.plansTitle'):wall.entry.title.replace(/\n/g,' ')" contained :resizable="false" :busy="processing" content-class="sf-premium-paywall__panel" @input="$emit('close')">
    <div class="sf-premium-paywall__navigation">
      <button v-if="isGuide||isPlans||backView" type="button" class="sf-premium-paywall__back" :aria-label="backLabel" :disabled="processing" @click="$emit('back')"><sf-icon name="back" :size="18"/></button>
      <sf-icon v-else name="membership" :size="17"/><span>SunnyFit <b>Premium</b></span>
    </div>
    <div v-show="isQuick" v-copy-block="{id:entryBlock,fields:((isConversation||generalOverview)?['title','description']:['title','description','unlock','category']).map(key=>'wall.entryStories.'+entryKind+'.'+key)}" class="sf-premium-paywall__quick" data-purchase-view="quick">
      <div v-if="isConversation" class="conversation-offer">
        <sf-ai-ball :size="56" decorative motion-policy="reduce"/>
        <h1 :data-copy-key="'wall.entryStories.'+entryKind+'.title'">{{ wall.entry.title }}</h1><p :data-copy-key="'wall.entryStories.'+entryKind+'.description'" class="sf-premium-paywall__subtitle">{{ wall.entry.description }}</p>
        <div v-if="draft" class="conversation-offer__draft"><span>Message saved</span><p>{{ draft }}</p></div>
        <div v-copy-block="{id:'paywall',fields:['paywall.coachBenefit','paywall.trainingBenefit']}" class="conversation-offer__benefits"><span><sf-icon name="coach" :size="18"/>{{ $copy('paywall.coachBenefit') }}</span><span><sf-icon name="play" :size="18"/>{{ $copy('paywall.trainingBenefit') }}</span></div>
      </div>
      <template v-else><div v-if="!generalOverview" class="sf-premium-paywall__resource">
        <img v-if="resourceImage" :src="resourceImage" alt=""/>
        <span v-else class="sf-premium-paywall__resource-icon"><sf-icon :name="wall.benefits[0].icon" :size="25"/></span>
        <div><small :data-copy-key="'wall.entryStories.'+entryKind+'.category'">{{ wall.entry.category }}</small><strong>{{ wall.resource.name }}</strong><span>{{ wall.resource.savedDraft?'Message saved':wall.resource.detail }}</span></div>
      </div>
      <h1 :data-copy-key="'wall.entryStories.'+entryKind+'.title'">{{ wall.entry.title }}</h1><p :data-copy-key="'wall.entryStories.'+entryKind+'.description'" class="sf-premium-paywall__subtitle">{{ wall.entry.description }}</p>
      <p v-if="!generalOverview" :data-copy-key="'wall.entryStories.'+entryKind+'.unlock'" class="sf-premium-paywall__unlock"><sf-icon name="check" :size="15"/>{{ wall.entry.unlock }}</p>
      </template>
      <sf-paywall-plans :offers="wall.offers" :selected-id="selectedId" :disabled="processing" @select="selectOffer" @reload="$emit('reload')"/>
      <button type="button" v-copy-block="{id:'paywall',fields:['paywall.learn','paywall.alsoDescription']}" class="sf-premium-paywall__learn sf-premium-paywall__beyond" :aria-label="$copy('paywall.learn')" :disabled="processing" @click="$emit('view','benefits')"><span class="sf-premium-paywall__banner-icon"><sf-icon name="membership" :size="22"/></span><span><strong data-copy-key="paywall.learn">{{ $copy('paywall.learn') }}</strong><small data-copy-key="paywall.alsoDescription">{{ $copy('paywall.alsoDescription',{benefits:otherBenefits}) }}</small></span><sf-icon name="arrow" :size="16"/></button>
    </div>
    <div v-show="isGuide" data-purchase-view="benefits">
      <sf-premium-guide :wall="wall" :benefit-id="benefitId" :disabled="processing" @benefit="$emit('benefit',$event)"/>
    </div>
    <section v-show="isPlans" class="sf-premium-paywall__plans-step" data-purchase-view="plans">
      <sf-paywall-plans :offers="wall.offers" :selected-id="selectedId" :disabled="processing" @select="selectOffer" @reload="$emit('reload')"/>
      <p v-copy-block="{id:'paywall',fields:['paywall.planDescription']}" class="sf-premium-paywall__subtitle">{{ $copy('paywall.planDescription') }}</p>
      <div v-if="!generalOverview" class="sf-premium-paywall__plan-task"><sf-icon :name="wall.benefits[0].icon" :size="20"/><div><strong>{{ wall.resource.name }}</strong><span>{{ wall.resource.detail }}</span></div></div>
      <button type="button" class="sf-premium-paywall__plan-benefits" :disabled="processing" @click="$emit('view','benefits')">{{ $copy('paywall.learn') }}<sf-icon name="arrow" :size="15"/></button>
    </section>
    <p v-if="feedback" class="sf-premium-paywall__feedback" role="status">{{ feedback }}</p>
    <template #footer>
      <sf-button v-if="isGuide" v-copy-block="{id:'membership.discovery',fields:['membership.preview.plans']}" class="sf-premium-paywall__continue sf-premium-paywall__view-plans" :disabled="processing" @click="$emit('view','plans')">{{ $copy('membership.preview.plans') }}<sf-icon name="arrow" :size="16"/></sf-button>
      <sf-button v-else v-copy-block="{id:entryBlock,fields:['wall.placements.'+entryKind+'.'+(selectedOffer&&selectedOffer.trialDays?'trialCta':'cta')]}" :data-copy-key="'wall.placements.'+entryKind+'.'+(selectedOffer&&selectedOffer.trialDays?'trialCta':'cta')" class="sf-premium-paywall__continue" :disabled="!selectedOffer||processing" @click="$emit('purchase',selectedOffer)">{{ processing?processingLabel:selectedOffer?selectedOffer.cta:'Plans unavailable' }}</sf-button>
      <p v-if="!isGuide" class="sf-premium-paywall__disclosure">{{ disclosure }}</p>
      <div class="sf-premium-paywall__links"><button type="button" :disabled="processing" @click="$emit('restore')">Restore purchases</button><a :href="termsUrl" target="_blank" rel="noopener noreferrer">Terms</a><a :href="privacyUrl" target="_blank" rel="noopener noreferrer">Privacy</a></div>
    </template>
  </sf-sheet>
</template>
<script>
import SfSheet from './SfSheet'
import SfButton from './SfButton'
import SfIcon from './SfIcon'
import SfPaywallPlans from './SfPaywallPlans'
import SfPremiumGuide from './SfPremiumGuide'
import SfAiBall from './SfAiBall'
import wallStructure from '../../../config/subscription-wall.structure.json'
export default {
  name:'SfPaywall',components:{SfAiBall,SfSheet,SfButton,SfIcon,SfPaywallPlans,SfPremiumGuide},
  props:{open:Boolean,draft:String,wall:{type:Object,required:true},view:{type:String,default:'quick'},backView:String,positions:{type:Object,default:()=>({quick:0,benefits:0,plans:0})},benefitId:String,selectedId:String,processing:Boolean,processingLabel:{type:String,default:'Confirming purchase…'},feedback:String,disclosure:String,termsUrl:String,privacyUrl:String},
  data(){return {compact:false}},
  computed:{
    entryKind(){return Object.keys(wallStructure.placements).find(kind=>wallStructure.placements[kind].placementId===this.wall.placementId)},
    entryBlock(){return 'entry-'+this.entryKind},
    isGuide(){return this.view==='benefits'},
    isQuick(){return this.view==='quick'},
    isPlans(){return this.view==='plans'},
    isConversation(){return this.wall.placementId==='ai_coach.allowance_empty'},
    generalOverview(){return this.wall.placementId==='membership.explore'},
    backLabel(){return this.backView==='benefits'?'Back to Premium benefits':this.backView==='quick'?'Back to quick subscription':this.backView==='plans'?'Back to plans':this.generalOverview?'Back to Membership & Usage':'Back to activity'},
    selectedOffer(){return this.wall.offers.find(offer=>offer.offerId===this.selectedId)},
    otherBenefits(){return this.wall.benefits.slice(1).map(benefit=>this.wall.education.stories.find(story=>story.id===({allowance:'coach',program:'workouts',vision:'workouts'}[benefit.id]||benefit.id))?.label||benefit.title).join(' · ')},
    resourceImage(){const image=this.wall.resource.image||this.wall.entry.image;return image?(/^(https?:|data:|\/)/.test(image)?image:process.env.BASE_URL+image):''}
  },
  watch:{view(next,previous){const body=this.$el.querySelector('.sf-modal__body');if(!body)return;this.$emit('position',{view:previous||'quick',top:body.scrollTop});this.$nextTick(()=>{body.scrollTop=this.positions[next]||0;const focus=this.$el.querySelector('.sf-premium-paywall__back');if(focus)focus.focus({preventScroll:true})})}},
  mounted(){this.$nextTick(()=>{const panel=this.$el.querySelector('.sf-modal');if(!panel)return;const update=()=>{this.compact=panel.clientHeight<=650};update();if(typeof ResizeObserver!=='undefined'){this.wallObserver=new ResizeObserver(update);this.wallObserver.observe(panel)}this.$el.querySelector('.sf-modal__body').scrollTop=this.positions[this.view]||0})},
  beforeDestroy(){const body=this.$el.querySelector('.sf-modal__body');if(body)this.$emit('position',{view:this.view,top:body.scrollTop});if(this.wallObserver)this.wallObserver.disconnect()},
  methods:{selectOffer(offer){this.$emit('select',offer)}}
}
</script>
<style scoped>

