-premium-paywall__resource strong{display:block;font-size:15px;line-height:21px;font-weight:650;color:var(--sf-brand-blue);overflow-wrap:anywhere}.sf-premium-paywall__resource div>span{display:block;font-size:12px;line-height:18px;color:var(--sf-text-secondary);margin-top:3px}.sf-premium-paywall__quick h1{font-size:31px;line-height:35px;letter-spacing:-.9px;margin:0;font-weight:750;white-space:pre-line;color:var(--sf-brand-blue)}.sf-premium-paywall__subtitle{font-size:14px;line-height:22px;color:var(--sf-text-secondary);margin:12px 0 0}.sf-premium-paywall__unlock{display:flex;align-items:flex-start;gap:8px;margin:18px 0 0;font-size:13px;line-height:20px;color:var(--sf-brand-blue);font-weight:600}.sf-premium-paywall__unlock .sf-icon{flex-shrink:0;margin-top:2px}.sf-premium-paywall__beyond{margin-top:16px;padding-top:14px;border-top:1px solid #e7eaf0}.sf-premium-paywall__beyond>span{font-size:10px;letter-spacing:.8px;color:var(--sf-text-secondary);font-weight:600}.sf-premium-paywall__beyond p{margin:5px 0 0;font-size:13px;line-height:20px;color:var(--sf-brand-blue)}.sf-premium-paywall__continue{font-size:16px;min-height:52px;width:100%;border-radius:16px!important}.sf-premium-paywall__disclosure{font-size:12px;line-height:18px;color:var(--sf-text-secondary);text-align:center;margin:10px auto 0;max-width:340px}.sf-premium-paywall__learn{display:flex;align-items:center;justify-content:center;gap:7px;width:100%;min-height:44px;border:0;background:none;color:var(--sf-brand-blue);font:600 13px/20px var(--sf-font-family);cursor:pointer}.sf-premium-paywall__links{display:flex;gap:20px;align-items:center;justify-content:center}.sf-premium-paywall__links button,.sf-premium-paywall__links a{font:11px/17px var(--sf-font-family);color:var(--sf-text-secondary);background:none;border:0;min-height:44px;padding:7px 0;text-decoration:none;cursor:pointer}.sf-premium-paywall__feedback{font-size:13px;line-height:20px;color:var(--sf-text-secondary);margin:12px 0}.conversation-offer>.sf-ai-ball{display:block;margin:0 0 12px -7px}.conversation-offer__draft{margin:18px 0 0;padding:14px;background:#f3f5f8;border-radius:14px}.conversation-offer__draft>span{display:block;font-size:11px;line-height:16px;color:var(--sf-text-secondary)}.conversation-offer__draft p{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;font-size:14px;line-height:21px;color:var(--sf-brand-blue);margin:5px 0 0;white-space:pre-wrap}.conversation-offer__benefits{display:grid;gap:10px;margin-top:18px}.conversation-offer__benefits>span{display:flex;align-items:center;gap:9px;color:var(--sf-brand-blue);font-size:13px;line-height:20px}.conversation-offer__benefits .sf-icon{flex-shrink:0}.sf-premium-paywall.is-compact .sf-premium-paywall__resource{margin-bottom:16px}.sf-premium-paywall.is-compact .sf-premium-paywall__quick h1{font-size:28px;line-height:32px}.sf-premium-paywall.is-compact .sf-premium-paywall__navigation{height:54px}.sf-premium-paywall.is-compact >>> .sf-modal__footer{padding-top:10px;padding-bottom:4px}.sf-premium-paywall__learn:disabled{opacity:.5}.sf-premium-paywall :is(button,a):focus-visible{outline:2px solid var(--sf-brand-blue);outline-offset:3px}

.sf-premium-paywall__learn.sf-premium-paywall__beyond{display:flex;justify-content:flex-start;gap:11px;align-items:center;text-align:left;margin:19px 0 0;padding:12px;border-radius:14px;background:var(--sf-beige);border:1px solid #ece3d8;min-height:64px;width:100%}.sf-premium-paywall__banner-icon{display:grid;place-items:center;width:34px;height:38px;flex:none;color:var(--sf-action);background:#fff9;border-radius:11px}.sf-premium-paywall__beyond>span:nth-child(2){flex:1;min-width:0;letter-spacing:0}.sf-premium-paywall__beyond strong{display:block;font-size:12px;line-height:18px;font-weight:600;color:var(--sf-brand-blue)}.sf-premium-paywall__beyond small{display:block;font-size:11px;line-height:17px;margin-top:3px;color:var(--sf-text-secondary)}.sf-premium-paywall__beyond>.sf-icon{flex:none}.sf-premium-paywall__plans-step>.sf-paywall-plans{margin-top:4px}.sf-premium-paywall__plans-step >>> .sf-paywall-plans h2{font-size:27px;line-height:33px;letter-spacing:-.6px;margin-bottom:22px}.sf-premium-paywall__plans-step>.sf-premium-paywall__subtitle{font-size:13px;line-height:21px;margin-top:18px}.sf-premium-paywall__plan-task{display:flex;align-items:center;gap:11px;margin-top:24px;padding:14px;border-radius:14px;background:var(--sf-beige);color:var(--sf-brand-blue)}.sf-premium-paywall__plan-task>div{display:grid;gap:4px}.sf-premium-paywall__plan-task strong{font-size:13px;line-height:20px}.sf-premium-paywall__plan-task span{font-size:12px;line-height:18px;color:var(--sf-text-secondary)}.sf-premium-paywall__plan-benefits{display:flex;align-items:center;gap:7px;background:none;border:0;color:var(--sf-brand-blue);padding:8px 0;min-height:44px;font:500 12px/18px var(--sf-font-family);cursor:pointer;margin-top:18px}
